  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    required_set = set(required_symbols)

    # Build dictionaries
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n.get('parent')
        if p is not None:
            children.setdefault(p, []).append(n['id'])

    # Precompute descendants (including self) for each node
    descendants = {}
    def get_descendants(nid):
        if nid not in descendants:
            dset = {nid}
            for cid in children.get(nid, []):
                dset.update(get_descendants(cid))
            descendants[nid] = dset
        return descendants[nid]
    for n in nodes:
        get_descendants(n['id'])

    # All node ids
    all_ids = set(node_map.keys())
    active = set(all_ids)

    # Gather candidate nodes (removable, not required symbol, not root)
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
            break

    candidates = []
    for n in nodes:
        if (n['removable'] and 
            n['symbol'] not in required_set and 
            n['id'] != root_id):
            candidates.append(n)

    # Sort by depth descending, then id ascending (stable)
    candidates.sort(key=lambda x: (-x['depth'], x['id']))

    removed = []
    for cand in candidates:
        cid = cand['id']
        if cid not in active:
            continue
        # Check that no descendant is active
        descendant_set = descendants[cid]
        descendant_set.remove(cid)  # we only check descendants, not itself
        if descendant_set & active:
            continue  # retain this node because it has active descendants
        descendant_set.add(cid)  # restore
        # Simulate removal of this node's subtree (only itself since descendants inactive)
        # Get current symbols from active
        current_symbols = set()
        for nid in active:
            current_symbols.add(node_map[nid]['symbol'])
        # After removing this node, its symbol is removed
        new_symbols = current_symbols - {cand['symbol']}
        if required_set.issubset(new_symbols):
            active.remove(cid)
            removed.append(cid)

    retained = sorted(active)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained
    }"
}
